themeCss:
/* Tiny — Tiny (tiny.school), the AI dětem classroom: dark violet, yellow and Inter.
   Brand and logos © AI dětem z. ú. (tiny.school), for its own materials; the CSS is MIT like SlAIdy,
   the fonts are under the SIL Open Font Licence (fonts/). Taken from the RecSys Atlas platform's
   slaidy-themes.css, where the same look is used for AI dětem lessons. */
@font-face{font-family:"Inter";font-style:normal;font-weight:400 800;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:"Inter";font-style:normal;font-weight:400 800;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}

html[data-slaidy-theme="tiny"]{
 --th-head:"Inter",system-ui,sans-serif;--th-body:"Inter",system-ui,sans-serif;
 --th-body-w:400;--th-head-w:700;
 --th-ink:#241832;--th-text:#342546;--th-muted:#6F6488;
 --th-accent:#692638;--th-accent-ink:#692638;
 --th-sky:#AFA6CA;--th-sky-dark:#483B58;--th-sky-light:#F4F0FF;
 --th-callout:#F4F0FF;--th-callout-edge:#FFF062;
 --th-th-bg:#241832;--th-th-ink:#FFF062;--th-row:#F7F5FC;--th-line:#DCD6EC;
 --th-cover:radial-gradient(circle at 82% 70%,rgba(255,113,113,.28) 0,rgba(255,113,113,0) 34%),
   radial-gradient(circle at 88% 62%,rgba(255,240,98,.20) 0,rgba(255,240,98,0) 22%),#241832;
 --th-cover-ink:#fff;--th-cover-soft:#FFF062;
 --th-cover-logo:url(data:image/png;base64,);--th-cover-logo-w:150px;--th-cover-logo-h:69px;
 --th-close-logo:url(data:image/png;base64,);
 --th-foot-logo:url(data:image/png;base64,);--th-foot-logo-w:62px;--th-foot-logo-h:28px;
 --th-pill:#241832;
}

/* ---------- content slides ---------- */
html[data-slaidy-theme="tiny"] .stage{padding:40px 64px 80px;color:var(--th-ink)}
html[data-slaidy-theme="tiny"] .stage h2{font-family:var(--th-head);font-weight:var(--th-head-w);color:var(--th-ink);
 letter-spacing:-.015em;margin-bottom:20px}
html[data-slaidy-theme="tiny"] .stage .tx{font-family:var(--th-body);font-weight:var(--th-body-w);color:var(--th-text);line-height:1.38}
html[data-slaidy-theme="tiny"] .stage .tx b,html[data-slaidy-theme="tiny"] .stage .tx strong{font-weight:700;color:var(--th-ink)}
html[data-slaidy-theme="tiny"] .stage .tx li::marker{color:var(--th-accent);font-weight:700}
html[data-slaidy-theme="tiny"] .stage .tx h2.bh,html[data-slaidy-theme="tiny"] .stage .tx h3.bh{font-family:var(--th-head);font-weight:var(--th-head-w);color:var(--th-ink)}
html[data-slaidy-theme="tiny"] .stage .tx h4.bh{font-family:var(--th-head);color:var(--th-accent-ink);letter-spacing:.06em}
html[data-slaidy-theme="tiny"] .stage .tx h5.bh{color:var(--th-muted)}
html[data-slaidy-theme="tiny"] .stage .tx blockquote{background:var(--th-callout);border-left:6px solid var(--th-callout-edge);
 border-radius:0 14px 14px 0;padding:.45em .9em;margin:.5em 0;color:var(--th-ink);font-weight:600;font-size:1.08em}
html[data-slaidy-theme="tiny"] .stage .tx blockquote p:last-child{margin-bottom:0}
html[data-slaidy-theme="tiny"] .stage .tx a{color:var(--th-accent-ink);text-decoration:underline;text-decoration-thickness:1.5px;text-underline-offset:3px}
html[data-slaidy-theme="tiny"] .stage .tx code{background:var(--th-sky-light)}
html[data-slaidy-theme="tiny"] .stage .tx .rule{border-top:2px solid var(--th-line)}
/* tables: brand header band, quiet zebra rows */
html[data-slaidy-theme="tiny"] .stage .tx table{border-collapse:separate;border-spacing:0;font-size:.84em;line-height:1.3}
html[data-slaidy-theme="tiny"] .stage .tx th{background:var(--th-th-bg);color:var(--th-th-ink);font-family:var(--th-head);
 font-weight:600;text-transform:none;letter-spacing:0;font-size:.9em;padding:7px 12px;border:0;vertical-align:bottom}
html[data-slaidy-theme="tiny"] .stage .tx th:first-child{border-top-left-radius:10px}
html[data-slaidy-theme="tiny"] .stage .tx th:last-child{border-top-right-radius:10px}
html[data-slaidy-theme="tiny"] .stage .tx td{padding:6px 12px;border-bottom:1px solid var(--th-line)}
html[data-slaidy-theme="tiny"] .stage .tx tbody tr:nth-child(even) td{background:var(--th-row)}
/* footer: the SlAIdy header row, moved down — logo · lecture · n / total */
html[data-slaidy-theme="tiny"] .stage .hdr{position:absolute;left:64px;right:64px;bottom:20px;margin:0;height:40px;
 align-items:center;gap:18px;text-transform:none;letter-spacing:0;font:500 19px/1 var(--th-body);color:var(--th-muted)}
html[data-slaidy-theme="tiny"] .stage .hdr::before{content:"";flex:none;width:var(--th-foot-logo-w);height:var(--th-foot-logo-h);
 background:var(--th-foot-logo) left center/contain no-repeat}
html[data-slaidy-theme="tiny"] .stage .hdr .hpath{flex:1;font-size:0;color:var(--th-muted)}
html[data-slaidy-theme="tiny"] .stage .hdr .hpath::before{content:var(--slaidy-footer,"");font:500 19px/1 var(--th-body);
 padding-left:18px;border-left:1.5px solid var(--th-line)}
html[data-slaidy-theme="tiny"] .stage .hdr .pos{display:none}
html[data-slaidy-theme="tiny"] .stage .hdr .ix:not(:empty){color:var(--th-pill);font:600 16px/1 var(--th-body);
 border:1.5px solid var(--th-pill);border-radius:999px;padding:7px 13px 8px}
/* ---------- cover & closing ---------- */
html[data-slaidy-theme="tiny"] .stage.lay-cover,html[data-slaidy-theme="tiny"] .stage.lay-closing{background:var(--th-cover);
 color:var(--th-cover-ink);padding:64px 96px}
html[data-slaidy-theme="tiny"] .stage.lay-cover::before{content:"";position:absolute;left:96px;top:56px;
 width:var(--th-cover-logo-w);height:var(--th-cover-logo-h);background:var(--th-cover-logo) left center/contain no-repeat}
html[data-slaidy-theme="tiny"] .stage.lay-cover{padding-top:150px}
html[data-slaidy-theme="tiny"] .stage.lay-cover h2,html[data-slaidy-theme="tiny"] .stage.lay-closing h2{color:var(--th-cover-ink);
 font-weight:600;max-width:74%;letter-spacing:-.02em}
html[data-slaidy-theme="tiny"] .stage.lay-cover h2.big{font-size:calc(var(--d-title)*1.45)}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx{color:var(--th-cover-soft);max-width:62%}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx b,html[data-slaidy-theme="tiny"] .stage.lay-cover .tx strong,
html[data-slaidy-theme="tiny"] .stage.lay-closing .tx b,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx strong{color:var(--th-cover-ink)}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx .bh,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx .bh{color:var(--th-cover-soft)}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx blockquote,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx blockquote{background:none;
 border:0;padding:0;color:var(--th-cover-ink);font-family:var(--th-head);font-weight:500;font-size:1.3em}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx a,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx a{color:var(--th-cover-ink)}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx li::marker,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx li::marker{color:var(--th-cover-ink)}
/* closing: logo on top, everything centred (manual p. 16 "Tak čau!") */
html[data-slaidy-theme="tiny"] .stage.lay-closing{align-items:center;text-align:center}
html[data-slaidy-theme="tiny"] .stage.lay-closing::before{content:"";flex:none;width:92px;height:92px;margin-bottom:22px;
 background:var(--th-close-logo) center/contain no-repeat}
html[data-slaidy-theme="tiny"] .stage.lay-closing::before{width:190px;height:88px}
html[data-slaidy-theme="tiny"] .stage.lay-closing h2{max-width:82%;margin-left:auto;margin-right:auto}
html[data-slaidy-theme="tiny"] .stage.lay-closing .stack{align-self:stretch}
html[data-slaidy-theme="tiny"] .stage.lay-closing .tx{max-width:74%;margin:0 auto}
html[data-slaidy-theme="tiny"] .stage.lay-closing h2.big{font-size:calc(var(--d-title)*1.3);margin-bottom:18px}
html[data-slaidy-theme="tiny"] .stage.lay-closing{padding:48px 120px}
/* cover/closing body is credits and a line or two: quieter than content text */
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx{font-size:calc(var(--d-body)*.8);line-height:1.3}
html[data-slaidy-theme="tiny"] .stage.lay-cover .tx .gap,html[data-slaidy-theme="tiny"] .stage.lay-closing .tx .gap{height:22px}
